create or replace function public.mn13_public_document(source jsonb) returns jsonb language sql immutable security invoker set search_path='' as $$
 select jsonb_build_object('version',1,'updatedAt',source->'updatedAt','pageVisibility',coalesce(source->'pageVisibility','{"courses":true,"diary":true}'::jsonb),'courses',coalesce((select jsonb_agg(c - array['reviewNote','sourceNames','sourceImageFilenames','imageWidth','imageHeight']) from jsonb_array_elements(source->'courses') c where c->'visible'='true'::jsonb and coalesce(source#>>'{pageVisibility,courses}','true')='true'),'[]'::jsonb),'journals',coalesce((select jsonb_agg(j - array['reviewNote','sourceNames']) from jsonb_array_elements(source->'journals') j where j->'visible'='true'::jsonb and j->'consent'='true'::jsonb and coalesce(source#>>'{pageVisibility,diary}','true')='true'),'[]'::jsonb));
$$;
